/* ================== PARAMETER SAP ================== *//*SELECT FROM JDT1 T1 */DECLARE @FromDate DATE;DECLARE @ToDate   DATE;SET @FromDate = /* T1.RefDate */ N'[%0]';SET @ToDate   = /* T1.RefDate */ N'[%1]';/* SET @FromDate = '2020-03-01';SET @ToDate   = '2026-03-31'; *//* ================== DATA ================== */WITH WO AS(    SELECT        P.BELNR_ID,        P.BELPOS_ID,        P.ItemCode,        P.startzeit_struktur AS StartDate,        P.lieferdatum        AS DeliveryDate,        P.ABGKZ_DATE         AS CloseWODate,        IT.ItmsGrpCod,        IG.ItmsGrpNam,        IG.BalInvntAc AS InventoryAccount,        P.MENGE_VERBRAUCH AS Plan_Qty        FROM BEAS_FTPOS P      LEFT JOIN OITM IT         ON P.ItemCode = IT.ItemCode    LEFT JOIN OITB IG         ON IT.ItmsGrpCod = IG.ItmsGrpCod    WHERE	(		P.ABGKZ_DATE >= @FromDate		AND P.ABGKZ_DATE < DATEADD(DAY,1,@ToDate)	)	OR P.ABGKZ_DATE IS NULL),BOM AS(    SELECT        B.BELNR_ID,        B.BELPOS_ID,        B.ART1_ID AS ItemCode,        IT.ItmsGrpCod,        IG.ItmsGrpNam,        IG.BalInvntAc AS InventoryAccount,        B.menge_verbrauch AS [UNIT_BOM],        B.MENGE_JE        AS PER,        B.ME_VERBRAUCH    AS UNIT_BOM_UOM,        B.TOTALQUANTITY_WHUNIT AS Plan_Qty    FROM BEAS_FTSTL B    INNER JOIN WO W        ON B.BELNR_ID = W.BELNR_ID       AND B.BELPOS_ID = W.BELPOS_ID    LEFT JOIN OITM IT ON B.ART1_ID = IT.ItemCode    LEFT JOIN OITB IG ON IT.ItmsGrpCod = IG.ItmsGrpCod), GI AS(    SELECT        X.U_belnrid  AS BELNR_ID,        X.U_belposid AS BELPOS_ID,        X.ItemCode,        SUM(X.QtyOut - X.QtyIn) AS ActualQty,        SUM(X.ValueOut - X.ValueIn) AS ActualValue    FROM    (        /* ===== Issue NVL ===== */        SELECT            I1.U_belnrid,            I1.U_belposid,            I1.ItemCode,            SUM(I1.Quantity) AS QtyOut,            0 AS QtyIn,            SUM(I1.Quantity * I1.StockPrice) AS ValueOut,            0 AS ValueIn        FROM OIGE T0        INNER JOIN IGE1 I1 ON T0.DocEntry = I1.DocEntry        WHERE I1.U_belnrid IS NOT NULL        GROUP BY I1.U_belnrid, I1.U_belposid, I1.ItemCode        UNION ALL        /* ===== Return NVL về kho ===== */        SELECT            R1.U_belnrid,            R1.U_belposid,            R1.ItemCode,            0,            SUM(R1.Quantity),            0,            SUM(R1.Quantity * R1.StockPrice)        FROM OIGN T0        INNER JOIN IGN1 R1 ON T0.DocEntry = R1.DocEntry        WHERE R1.U_belnrid IS NOT NULL        GROUP BY R1.U_belnrid, R1.U_belposid, R1.ItemCode    ) X    GROUP BY        X.U_belnrid,        X.U_belposid,        X.ItemCode),FG_ACTUAL AS(    SELECT        X.U_belnrid  AS BELNR_ID,        X.U_belposid AS BELPOS_ID,        X.ItemCode,        SUM(X.QtyIn - X.QtyOut) AS ActualQty,        SUM(X.ValueIn - X.ValueOut) AS ActualValue    FROM    (        /* ===== Receipt FG ===== */        SELECT            R1.U_belnrid,            R1.U_belposid,            R1.ItemCode,            SUM(R1.Quantity) AS QtyIn,            0 AS QtyOut,            SUM(R1.Quantity * R1.StockPrice) AS ValueIn,            0 AS ValueOut        FROM OIGN T0        INNER JOIN IGN1 R1 ON T0.DocEntry = R1.DocEntry        WHERE R1.U_belnrid IS NOT NULL        GROUP BY R1.U_belnrid, R1.U_belposid, R1.ItemCode        UNION ALL        /* ===== Issue FG (nếu có xuất trả / sai) ===== */        SELECT            I1.U_belnrid,            I1.U_belposid,            I1.ItemCode,            0,            SUM(I1.Quantity),            0,            SUM(I1.Quantity * I1.StockPrice)        FROM OIGE T0        INNER JOIN IGE1 I1 ON T0.DocEntry = I1.DocEntry        WHERE I1.U_belnrid IS NOT NULL        GROUP BY I1.U_belnrid, I1.U_belposid, I1.ItemCode    ) X    GROUP BY        X.U_belnrid,        X.U_belposid,        X.ItemCode)/* ================== BEAS COST DETAIL (CHUẨN BEAS) ================== */, BEAS_COST_DETAIL AS(    /* 1. BEAS JOURNAL HISTORIE */    SELECT        J.TransId,        J.U_belnrid  AS BELNR_ID,        J.U_belposid AS BELPOS_ID,        O.AcctCode   AS Account,        J.Debit,        J.Credit    FROM BEAS_JOURNAL_HISTORIE J    LEFT JOIN OACT O ON J.Account = O.AcctCode    WHERE J.U_belnrid IS NOT NULL      AND J.U_belposid IS NOT NULL    UNION ALL    /* 2. JE thường (không GI/GR) */    SELECT        J.TransId,        OJ.U_belnrid,        OJ.U_belposid,        O.AcctCode,        J.Debit,        J.Credit    FROM JDT1 J    INNER JOIN OJDT OJ ON OJ.TransId = J.TransId    LEFT JOIN OACT O ON J.Account = O.AcctCode    WHERE OJ.TransType NOT IN (59,60)      AND OJ.U_belnrid IS NOT NULL      AND OJ.U_belposid IS NOT NULL    UNION ALL    /* 3. Goods Issue – NVL */    SELECT DISTINCT        J.TransId,        I1.U_belnrid,        I1.U_belposid,        O.AcctCode,        J.Debit,        J.Credit    FROM JDT1 J    INNER JOIN OJDT OJ ON OJ.TransId = J.TransId    INNER JOIN OIGE OG ON OJ.CreatedBy = OG.DocEntry    INNER JOIN IGE1 I1 ON OG.DocEntry = I1.DocEntry    LEFT JOIN OACT O ON J.Account = O.AcctCode    WHERE OJ.TransType = 60      AND I1.U_belnrid  IS NOT NULL      AND I1.U_belposid IS NOT NULL    UNION ALL    /* 4. Goods Receipt – FG */    SELECT DISTINCT        J.TransId,        R1.U_belnrid,        R1.U_belposid,        O.AcctCode,        J.Debit,        J.Credit    FROM JDT1 J    INNER JOIN OJDT OJ ON OJ.TransId = J.TransId    INNER JOIN OIGN ORH ON OJ.CreatedBy = ORH.DocEntry    INNER JOIN IGN1 R1 ON ORH.DocEntry = R1.DocEntry    LEFT JOIN OACT O ON J.Account = O.AcctCode    WHERE OJ.TransType = 59      AND R1.U_belnrid IS NOT NULL      AND R1.U_belposid IS NOT NULL)/* ================== COST_BEAS (GIỐNG COST_PIVOT) ================== */, COST_BEAS AS(    SELECT        BELNR_ID,        BELPOS_ID,        SUM(CASE WHEN Account = '6229'  THEN Debit - Credit ELSE 0 END) AS C_6229,        SUM(CASE WHEN Account = '1542'  THEN Debit - Credit ELSE 0 END) AS C_1542,        SUM(CASE WHEN Account = '62719' THEN Debit - Credit ELSE 0 END) AS C_62719,        SUM(CASE WHEN Account = '62725' THEN Debit - Credit ELSE 0 END) AS C_62725,        SUM(CASE WHEN Account = '1551'  THEN Debit - Credit ELSE 0 END) AS C_1551,        SUM(CASE WHEN Account = '1521'  THEN Debit - Credit ELSE 0 END) AS C_1521,        SUM(CASE WHEN Account = '1541'  THEN Debit - Credit ELSE 0 END) AS C_1541,        SUM(CASE WHEN Account = '1552'  THEN Debit - Credit ELSE 0 END) AS C_1552    FROM BEAS_COST_DETAIL    GROUP BY BELNR_ID, BELPOS_ID)/* ================== FINAL ================== */SELECT *FROM(    /* ===== FG ===== */    SELECT        W.BELNR_ID  AS [WO],        W.BELPOS_ID AS [WO POS],        W.StartDate     AS [Start Date],        W.DeliveryDate  AS [Delivery Date],        W.CloseWODate   AS [Close WO Date],        W.ItemCode,        W.ItmsGrpCod AS [Item groups code],        W.ItmsGrpNam AS [Item groups Name],        W.InventoryAccount AS [Inventory Account code],        NULL AS UNIT_BOM,        NULL AS PER,        NULL AS UNIT_BOM_UOM,        W.Plan_Qty,        ISNULL(FG.ActualQty,0) AS Actual_QTY,        CAST(            ISNULL(FG.ActualValue,0) /            NULLIF(FG.ActualQty,0)        AS DECIMAL(18,2)) AS [UNIT (Actual VALUE /Actual QTY)],        ISNULL(FG.ActualValue,0) AS Actual_VALUE,        /* ===== COST FLOW ===== */	 ISNULL(CB.C_6229,0)  AS [6229],	ISNULL(CB.C_1542,0)  AS [1542],	ISNULL(CB.C_62719,0) AS [62719],	ISNULL(CB.C_62725,0) AS [62725],	ISNULL(CB.C_1551,0)  AS [1551],	ISNULL(CB.C_1521,0)  AS [1521],	ISNULL(CB.C_1541,0)  AS [1541],	ISNULL(CB.C_1552,0)  AS [1552]    FROM WO W    LEFT JOIN FG_ACTUAL FG        ON W.BELNR_ID  = FG.BELNR_ID       AND W.BELPOS_ID = FG.BELPOS_ID       AND W.ItemCode  = FG.ItemCode    LEFT JOIN COST_BEAS CB        ON W.BELNR_ID  = CB.BELNR_ID       AND W.BELPOS_ID = CB.BELPOS_ID    UNION ALL        SELECT        B.BELNR_ID,        B.BELPOS_ID,        NULL,        NULL,        NULL,        B.ItemCode,        B.ItmsGrpCod,        B.ItmsGrpNam,        B.InventoryAccount,        B.UNIT_BOM,        B.PER,        B.UNIT_BOM_UOM,        -B.Plan_Qty,        -ISNULL(GI.ActualQty,0),        CAST(ISNULL(GI.ActualValue,0) / NULLIF(GI.ActualQty,0) AS DECIMAL(18,2)),        -ISNULL(GI.ActualValue,0),		NULL, -- 6229		NULL, -- 1542		NULL, -- 62719		NULL, -- 62725		NULL, -- 1551		NULL, -- 1521		NULL, -- 1541		NULL  -- 1552    FROM BOM B    LEFT JOIN GI        ON B.BELNR_ID  = GI.BELNR_ID       AND B.BELPOS_ID = GI.BELPOS_ID       AND B.ItemCode  = GI.ItemCode) X--WHERE X.WO = '9760'ORDER BY    [WO],    [WO POS],    CASE WHEN UNIT_BOM IS NULL THEN 0 ELSE 1 END,    ItemCode,    [Inventory Account code];